contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We'll call withdrawReward on an arbitrary recipient and check that the _locked flag
    // (public in SmartFix) is false after the call when observed; if the call reverts that's allowed,
    // but if it returns then _locked must be false. To observe before/after we read c._locked().
    function run(address recipient) public payable {
        require(true);

        // observe locked before
        bool lockedBefore = c._locked(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawReward(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe locked after
        bool lockedAfter = c._locked(); if (__ESBMC_reverted()) return;

        // General rule: the contract's non-reentrancy lock should not remain set after the call;
        // i.e., if the call succeeded (didn't revert) then lockedAfter must be false, and if it
        // was false before, it must still be false after success. We express this as: if not reverted
        // then lockedAfter == false. This is a non-trivial property ensured by the modifier.
        assert(reverted || lockedAfter == false);
    }

    // receive just so the test contract can accept Ether if needed by calls
    receive() external payable {}
}

